<script setup lang="ts">
import { computed } from 'vue'

const props = withDefaults(
  defineProps<{
    provider: string
    size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | number
    rounded?: boolean
    withBg?: boolean
    bgColor?: string
  }>(),
  {
    size: 'md',
    rounded: true,
    withBg: false,
  }
)

const resolvedProvider = computed(() => (props.provider || '').toLowerCase())

/** 智谱相关的多种写法统一识别（zhipu / glm / chatglm / bigmodel 等） */
const isZhipu = computed(() =>
  ['zhipu', 'glm', 'zhipuai', 'chatglm', 'bigmodel'].includes(resolvedProvider.value)
)

/** Tavily 联网搜索引擎统一识别 */
const isTavily = computed(() =>
  ['tavily', 'tavily_proxy'].includes(resolvedProvider.value)
)

const sizeMap: Record<string, number> = {
  xs: 18,
  sm: 22,
  md: 28,
  lg: 36,
  xl: 44,
}

const pixelSize = computed(() => {
  if (typeof props.size === 'number') return props.size
  return sizeMap[props.size] || 28
})

const containerStyle = computed(() => {
  const s = `${pixelSize.value}px`
  const style: Record<string, string> = {
    width: s,
    height: s,
  }
  if (props.withBg && props.bgColor) {
    style.backgroundColor = props.bgColor
  }
  return style
})
</script>

